def sort_array(array):
    if not array:
        return []

    first = array[0]
    last = array[-1]
    sorted_array = array.copy()

    if (first + last) % 2 == 0:
        sorted_array.sort(reverse=True)
    else:
        sorted_array.sort()

    return sorted_array
